mapper.select:
select t.parking_type,t.parking_type parkingType,t.num,t.pa_id,t.pa_id paId,t.ps_id,t.ps_id
psId,t.remark,t.status_cd,t.status_cd statusCd,t.state,t.community_id,t.community_id communityId,
t.create_time createTime,pa.num paNum,psmr.ps_state psState,psmr.car_num parkCarNum,
psmr.lock_battery lockBattery,psmr.lock_state lockState,psmr.image_photo imagePhoto,psmr.update_time updateTime,
psm.machine_name machineName,psm.heartbeat_time heartbeatTime,t.pr_id prId,pr.region_code regionCode,
t.monitor_id monitorId,t.monitor_name monitorName,
t.owner_id ownerId,t.owner_name ownerName,t.car_id carId,t.car_num carNum,
t.start_time startTime,t.end_time endTime
from parking_space t
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
left join parking_space_machine_rel psmr on t.ps_id = psmr.ps_id and psmr.status_cd = '0'
left join parking_space_machine psm on psmr.machine_id = psm.machine_id and psm.status_cd = '0'
left join parking_region pr on t.pr_id = pr.pr_id and pr.status_cd = '0'
where 1 =1

    and psm.machine_code = #{machineCode}


    and psm.machine_name = #{machineName}


    and t.parking_type= #{parkingType}


    and t.num= #{num}


    and t.pa_id= #{paId}


    and t.pr_id= #{prId}


    and pr.region_code= #{regionCode}


    and t.ps_id= #{psId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.monitor_id= #{monitorId}


    and t.monitor_name= #{monitorName}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update parking_space t set t.status_cd = #{statusCd}

    , t.parking_type= #{parkingType}


    , t.num= #{num}


    , t.pa_id= #{paId}


    , t.pr_id= #{prId}


    , t.remark= #{remark}


    , t.state= #{state}


    , t.monitor_id= #{monitorId}


    , t.monitor_name= #{monitorName}


    , t.owner_id= nullif(#{ownerId}, '')


    , t.owner_name= nullif(#{ownerName}, '')


    , t.car_id= nullif(#{carId}, '')


    , t.car_num= nullif(#{carNum}, '')


    , t.start_time= nullif(#{startTime}, '')


    , t.end_time= nullif(#{endTime}, '')

where 1=1

    and t.ps_id= #{psId}


    and t.community_id= #{communityId}

mapper.select:
