from parking_space t
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
left join parking_space_machine_rel psmr on t.ps_id = psmr.ps_id and psmr.status_cd = '0'
left join parking_space_machine psm on psmr.machine_id = psm.machine_id and psm.status_cd = '0'
left join parking_region pr on t.pr_id = pr.pr_id and pr.status_cd = '0'
where 1 =1

    and psm.machine_code = #{machineCode}


    and psm.machine_name = #{machineName}


    and t.parking_type= #{parkingType}


    and t.num= #{num}


    and t.pa_id= #{paId}


    and t.pr_id= #{prId}


    and pr.region_code= #{regionCode}


    and t.ps_id= #{psId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.monitor_id= #{monitorId}


    and t.monitor_name= #{monitorName}
